"use client";import {useEffect,useState} from 'react'; export default function Promo(){ const [rows,setRows]=useState<any[]>([]); const [code,setCode]=useState('WELCOME10'); const [pct,setPct]=useState(10); async function load(){ const r=await fetch('/admin/promo/list'); const js=await r.json(); setRows(js.rows||[]); } async function create(){ await fetch('/admin/promo/create',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({code,percent_off:Number(pct)})}); load(); } async function toggle(c:string,a:boolean){ await fetch('/admin/promo/toggle',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({code:c, active:a})}); load(); }
useEffect(()=>{ load(); },[]);
return(<div className='max-w-3xl mx-auto py-8'><h1 className='text-xl font-bold'>Promo Codes</h1><div className='flex gap-2 mt-2'><input className='p-2 border rounded' value={code} onChange={e=>setCode(e.target.value)}/><input className='p-2 border rounded w-24' type='number' value={pct} onChange={e=>setPct(Number(e.target.value))}/><button className='px-3 py-2 bg-black text-white rounded' onClick={create}>Create/Update</button></div><div className='mt-4 space-y-2'>{rows.map((r:any)=>(<div key={r.code} className='p-3 border rounded text-sm flex items-center justify-between'><div><b>{r.code}</b> — {r.percent_off}% {r.active?'• active':'• inactive'}</div><div className='flex gap-2'><button className='px-2 py-1 border rounded' onClick={()=>toggle(r.code,true)}>Activate</button><button className='px-2 py-1 border rounded' onClick={()=>toggle(r.code,false)}>Deactivate</button></div></div>))}</div></div>);}
